using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00028 : ControllerTestBase
    {
        [TestMethod]
        public void Should_Declare_Correct_ProduceResponseTypes_For_200_OK_With_Same_ResponseType_Like_The_Method()
        {
            var incorrectResponseTypeInAttribute = (from controller in Controllers
                                                    from method in controller.Methods
                                                    where method.ReturnParameter.DoesNotContain("ActionResult") &&
                                                          method.ReturnParameter.DoesNotContain("IActionResult")
                                                    let attributes = method.Attributes.Where(a => a.Name.StartWith("ProducesResponseType"))
                                                    where attributes.Any(a =>
                                                    {
                                                        var result = a.Arguments.Any(arg => arg == "StatusCodes.Status200OK") &&
                                                                     a.Arguments.Any(arg => arg.Contains(method.ReturnParameter.Replace("Task<", string.Empty).TrimEnd('>')) ||
                                                                                            (a.Arguments.All(a => !a.Contains("typeof")) && method.ReturnParameter == nameof(Task)));
                                                        return result;
                                                    }).IsFalse()
                                                    select new
                                                    {
                                                        Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:     

[ProducesResponseType(typeof({method.ReturnParameter.Replace("Task<", string.Empty).TrimEnd('>')}), StatusCodes.Status200OK)]
{method.ReturnParameter} {method.Name}({method.Parameters.Select(p => $"{p.Type} {p.Name}").Flatten(", ")})
{{               
    return _mediator.SendAsync(new GetData());
}}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                                    }).ToImmutableList();

            Assert.IsTrue(incorrectResponseTypeInAttribute.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00028

'ProduceResponseType' for 'StatusCodes.Status200OK' does not contain correct type: {Environment.NewLine}{incorrectResponseTypeInAttribute.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
